class Budget:
    def __init__(self, total):
        self.total, self.used = total, 0
    def run(self, n):
        if self.used + n > self.total:
            raise RuntimeError('simulation budget exhausted')
        self.used += n

b = Budget(324)
for design in range(81):
    b.run(3)
try:
    b.run(100)
except RuntimeError as e:
