import numpy as np

def by_position(tasks):
    kids = np.random.SeedSequence(20).spawn(len(tasks))
    return {t: np.random.default_rng(k).random() for t, k in zip(tasks, kids)}

def by_identity(task):
    return np.random.default_rng(np.random.SeedSequence(20, spawn_key=task)).random()

tasks = [(s, r) for s in range(3) for r in range(2)]
clean, resumed = by_position(tasks), by_position(tasks[4:])
print(clean[(2, 0)] == resumed[(2, 0)], by_identity((2, 0)) == by_identity((2, 0)))

